@module viewContext  src=viewContext.lua  loc=130  mode=chunk  self=ctx
@deps length, numRows, rowPerBeat, ppqPerRow, timeSigs, temper

# Shapes
  @shape  args = { length, numRows, rowPerBeat, ppqPerRow, timeSigs, temper }  @ 6

# Imports
  @require util = 'util'  @ 7
      @invariant  pure: no side effects, no signals, no mutation of args  @ 4
      @invariant  identity row math: ppqToRow and rowToPPQ are exact inverses under uniform ppqPerRow; both return float. "on the grid" is a tolerance question, owned by ctx:isOnGrid (PPQ_GRID_EPS).  @ 5
  @require tuning = 'tuning'  @ 8

# Private state
  @state length = args.length  @ 12
  @state numRows = args.numRows  @ 13
  @state rowPerBeat = args.rowPerBeat  @ 14
  @state ppqPerRow = args.ppqPerRow  @ 15
  @state timeSigs = args.timeSigs  @ 16
  @state temper = args.temper  @ 17
  @state ctx = {}  @ 18
  @state ON_TEMPER_EPS = 1e-6  @ 26
  @state PPQ_GRID_EPS = 0.5  @ 74

# Private functions
  -- Temperament
  -- Timing
  @fn timeSigAt(ppq)  @ 93-100
  @fn tsRow(ts)  @ 102

# Public API (ctx:*)
  @api ctx:activeTemper()  @ 22
  @api ctx:noteLabel(evt)  @ 29-33
      @contract  (note, octaveLabel, negative) for the note's step, or nil with no temper bound  @ 28
  @api ctx:noteDeviation(evt)  @ 36-48
      @contract  (gap, half) in cents off the note's step; half is the gap-side window half, nil unbound  @ 35
  @api ctx:ppqToRow(ppqI, chan)  @ 53-57
      @contract  identity row math: column-event ppq is the logical position; rows are uniform ppqPerRow units. Exact inverse of rowToPPQ. Returns float; integer rows are float fixpoints. The chan argument is unused at this layer (kept for the call-site signature).  @ 52
  @api ctx:rowToPPQ(row, chan)  @ 60-64
      @contract  identity row math: row × ppqPerRow, clamped at length. Returns float; no rounding. On-grid is a tolerance question — see ctx:isOnGrid.  @ 59
  @api ctx:snapRow(ppqI, chan)  @ 66
  @api ctx:ppqPerRow()  @ 68
  @api ctx:isOnGrid(ppqI, chan)  @ 77-80
      @contract  true iff ppqI lies within PPQ_GRID_EPS ppq of the nearest row's ppq under this ctx. The sole owner of the on-grid threshold; callers must not re-implement it from rowToPPQ.  @ 76
  @api ctx:placeRow(ppqI, chan)  @ 85-90
      -- The place loop asks all three of these questions of every event; asking
      -- them separately re-derives the same row ~16 method calls deep.
      @contract  one row computation; returns (row, cellRow, onGrid) ≡ (ppqToRow, ppqRowOf, isOnGrid)  @ 84
  @api ctx:rowBeatInfo(row)  @ 104-109
  @api ctx:barBeatSub(row)  @ 111-127

# Uses (outbound edges)
  @use call    tuning.midiToStep  @ noteLabel:31 noteDeviation:39
  @use call    tuning.stepToMidi  @ noteDeviation:40
  @use call    tuning.stepToParts  @ noteLabel:32
  @use call    tuning.stepWindow  @ noteDeviation:46
  @use call    util.round  @ snapRow:66 placeRow:87
  @use require tuning  @ <load>:8
  @use require util  @ <load>:7

# Calls (intra-file)
  @call ctx:ppqToRow  @ snapRow:66 placeRow:86 tsRow:102
  @call ctx:rowToPPQ  @ isOnGrid:78 placeRow:88 rowBeatInfo:105
  @call ctx:snapRow  @ isOnGrid:78
  @call timeSigAt  @ rowBeatInfo:105
  @call tsRow  @ rowBeatInfo:107 barBeatSub:116,118,124

# Fields (r read / w write incl. constructor keys)
  @field r detune  @ noteLabel:31 noteDeviation:38
  @field r huge  @ barBeatSub:116
  @field r length  @ 12
  @field r num  @ rowBeatInfo:108 barBeatSub:114
  @field r numRows  @ 13
  @field r pitch  @ noteLabel:30,31 noteDeviation:37,39,41
  @field r ppq  @ timeSigAt:96 tsRow:102
  @field r ppqPerRow  @ 15
  @field r rowPerBeat  @ 14
  @field r temper  @ 17
  @field r timeSigs  @ 16
